import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"50、【鼎】 巽下离上","description":"子夏易传 - 50、【鼎】 巽下离上","frontmatter":{"title":"50、【鼎】 巽下离上","description":"子夏易传 - 50、【鼎】 巽下离上"},"headers":[],"relativePath":"zh/classics/zixia/052.md","filePath":"zh/classics/zixia/052.md"}'),i={name:"zh/classics/zixia/052.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_50、【鼎】-巽下离上" tabindex="-1">50、【鼎】 巽下离上 <a class="header-anchor" href="#_50、【鼎】-巽下离上" aria-label="Permalink to “50、【鼎】 巽下离上”">​</a></h1><p>卦辞：鼎，元吉亨。</p><p>彖曰：鼎，象也。以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢。巽而耳目聦明，柔進而上行，得中而應乎，剛是以元亨。</p><p>子夏：天下者，神器也。鼎者大器也。其治之者，必有法也，故以治鼎為法焉。離巽合而成象矣。趾分其初也，次實腹也，中虚耳也。上剛鉉也，故曰鼎，象也。其義以木巽火也。有亨飪之道也。聖人南面而設制度，使天下以器，而治其大器，則物无滯矣。則固矣，故曰鼎。取新也。利出否焉，不置其器者也。治其器必以制度，制之道莫上乎立敬，立敬莫先乎享上帝，此制度之先也。鼎用多而致治者，莫若乎養聖賢。此其器也，得其器行其事然後能為天下王聖。人巽於聖賢，則明矣。以天下之目視也，以天下之耳聽也，於何而不至焉。柔得大位，歛身若不足，故天下歸之。剛上而尊賢，剛而任能也。則天下何有焉。是以大有慶而能通也。</p><p>象曰：木上有火，鼎。君子以正位凝命。</p><p>子夏：木上有火，爨鼎之道。治鼎者也，當聖人養賢使能也。君子正位守職，成聖人之命也。</p><p>初六，鼎顚趾，利出否。得妾以其子，无咎。</p><p>象曰：鼎顚趾，未悖也。利出否，以從貴也。</p><p>子夏：下鼎趾也，上應顚也。治鼎之道，用鼎之始也。應滌覆否，顚之利也。妾本下也，而以孚升士，雖賤而才貴。火上從而致其新也。可无咎矣。夫制者，有位而從權，雖反可也。</p><p>九二，鼎有實，我仇有疾，不我能，即吉。</p><p>象曰：鼎有實，愼所之也。我仇有疾，終无尤也。</p><p>子夏：剛以中應而承其實，任之重者矣。四以近權，惡我專任，怨偶敵我，不可以不愼其所行。然九四之覆，餗正无幾矣。豈暇謀我哉。獲其終吉也矣。</p><p>九三，鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。</p><p>象曰：鼎耳革，失其義也。</p><p>子夏：尊柔非應，而革於四，鼎耳所以待實而將用也。革則我道不通也。雉膏焉得而食哉。夫君子之修徳，用其知也，欲其效也，无已知以應，不能進也，安得其任哉。失修徳之義也。當鼎新主，耳目聦眀，以柔徳接之，獨見以進則悔虧而終吉也。</p><p>九四，鼎折足，覆公餗，其形渥，凶。</p><p>象曰：覆公餗，信如何也。</p><p>子夏：以不中之才當鼎食之寵，事上與下，力何任焉，折足者矣。非唯足折，亦虧公任也。公任虧則受凶。渥者，形濡什而不勝也。非所任而任，以至於此，信有凶矣，如之何哉。</p><p>六五，鼎黄耳金鉉，利貞。</p><p>象曰：鼎黄耳，中以為實也。</p><p>子夏：文而虚中，待鉉以載也，故能應剛而任重之矣。尊柔以能，利而得正也。</p><p>上九，鼎玉鉉，大吉。无不利。</p><p>象曰：玉鉉在上，剛柔節也。</p><p>子夏：剛上而尊，賢助以載鼎也。玉鉉者，貴於金而不當用也。剛能聦逹，茍柔奉之巽，而以順得其節矣。器大治矣，故大吉而无不利也。</p>',24)])])}const h=a(i,[["render",r]]);export{f as __pageData,h as default};
